import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {execFileSync} from 'node:child_process';
import {performance} from 'node:perf_hooks';
import {storageRegistration,withDirectoryAdmission,requireAdmission,closeStorageAdmissions} from './packages/room-mcp/src/storage-admission.ts';
const root=fs.mkdtempSync(path.join(os.tmpdir(),'room-lazy-cost-'));
try {
execFileSync('git',['init','-q',root]);
const common=path.join(root,'.git');
await storageRegistration(common);
for(let i=0;i<3;i++) await withDirectoryAdmission(root,'collect',async()=>{await requireAdmission(common)});
const values=[];
for(let i=0;i<30;i++) {const at=performance.now(); await withDirectoryAdmission(root,'collect',async()=>{await requireAdmission(common)});values.push(performance.now()-at)}
const at=performance.now();
for(let i=0;i<10000;i++) await withDirectoryAdmission(undefined,'collect',async()=>{});
const emptyTotalMs=performance.now()-at;
values.sort((a,b)=>a-b);
console.log('BENCHMARK '+JSON.stringify({platform:process.platform,arch:process.arch,node:process.version,filesystemType:fs.statfsSync(root).type,samples:30,warmup:3,concurrency:1,operation:'warmed lazy scope, requireAdmission, finish; no lifecycle body',p50Ms:values[15],p95Ms:values[28],meanMs:values.reduce((a,b)=>a+b,0)/values.length,emptyCalls:10000,emptyTotalMs}));
} finally {await closeStorageAdmissions();fs.rmSync(root,{recursive:true,force:true})}
